    private void btnIniciarActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_btnIniciarActionPerformed
        int maximo, p1, p2;
        try {
            maximo = Integer.parseInt(txtMaximo.getText().trim());
            p1 = Integer.parseInt(txtPrioridade1.getText().trim());
            p2 = Integer.parseInt(txtPrioridade2.getText().trim());
        } catch (NumberFormatException ex) {
            javax.swing.JOptionPane.showMessageDialog(this, "Informe apenas números inteiros.");
            return;
        }
        if (maximo < 1 || p1 < 1 || p1 > 10 || p2 < 1 || p2 > 10) {
            javax.swing.JOptionPane.showMessageDialog(this,
                    "O máximo deve ser maior que zero e as prioridades devem estar entre 1 e 10.");
            return;
        }
        btnIniciar.setEnabled(false);
        btnLimpar.setEnabled(false);
        threadsEmAndamento = 2;
        painel1.iniciar(maximo, p1, this::threadTerminou);
        painel2.iniciar(maximo, p2, this::threadTerminou);
    }//GEN-LAST:event_btnIniciarActionPerformed

    private void btnLimparActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_btnLimparActionPerformed
        painel1.limpar();
        painel2.limpar();
        if (threadsEmAndamento > 0) {
            threadsEmAndamento = 0;
            btnIniciar.setEnabled(true);
            btnLimpar.setEnabled(true);
        }
    }//GEN-LAST:event_btnLimparActionPerformed

    private int threadsEmAndamento = 0;

    private void threadTerminou() {
        threadsEmAndamento--;
        if (threadsEmAndamento == 0) {
            btnIniciar.setEnabled(true);
            btnLimpar.setEnabled(true);
        }
    }

